int maxArea(int *height, int heightSize) {
  int min = 0, max = heightSize - 1;
  int area_max = 0;
  while (min < max) {
    int area = (max - min) * (height[min] < height[max] ? height[min] : height[max]);
    area_max = area > area_max ? area : area_max;
    if (height[min] < height[max]) {
      min++;
    } else {
      max--;
    }
  }
  return area_max;
}

class Solution {
public:
  int maxArea(vector<int> &height) {
    int left = 0, right = height.size() - 1, best = 0;
    while (left < right) {
      int h = min(height[left], height[right]);
      best = max(best, (right - left) * h);
      if (height[left] < height[right]) {
        left++;
      } else {
        right--;
      }
    }
    return best;
  }
};

//双指针法
func maxArea(height []int) int {
	j := len(height) - 1 // right 指针
	i := 0               // left 指针
	min := 0
	max := 0

	for i < j { //tmp需要提前计算出来
		tmp := j - i
		if height[i] < height[j] {
			min = height[i]
			i++
		} else {
			min = height[j]
			j--
		}
		if tmp*min > max {
			max = tmp * min
		}
	}
	return max
}

class Solution {
  public int maxArea(int[] height) {
    int left = 0, right = height.length - 1, best = 0;
    while (left < right) {
      int h = Math.min(height[left], height[right]);
      best = Math.max(best, (right - left) * h);
      if (height[left] < height[right]) {
        left++;
      } else {
        right--;
      }
    }
    return best;
  }
}

class Solution:
    def maxArea(self, height: List[int]) -> int:
        left, right, best = 0, len(height) - 1, 0
        while left < right:
            h = min(height[left], height[right])
            best = max(best, (right - left) * h)
            if height[left] < height[right]:
                left += 1
            else:
                right -= 1
        return best

impl Solution {
  pub fn max_area(height: Vec<i32>) -> i32 {
    let (mut left, mut right, mut best) = (0usize, height.len() - 1, 0i32);
    while left < right {
      let h = height[left].min(height[right]);
      best = best.max((right - left) as i32 * h);
      if height[left] < height[right] {
        left += 1;
      } else {
        right -= 1;
      }
    }
    best
  }
}

const maxArea = (height: number[]): number => {
  let left = 0;
  let right = height.length - 1;
  let best = 0;

  while (left < right) {
    const h = Math.min(height[left], height[right]);
    best = Math.max(best, (right - left) * h);
    if (height[left] < height[right]) left++;
    else right--;
  }

  return best;
};
